-- The rarity pyramid: more commons than uncommons, more uncommons than rares, and some rares up to epic.
-- 79 creatures move (14 rare→epic, 33 rare→uncommon, 32 uncommon→common); legendaries stay. GENERATED by
-- scripts/build-historikals.mjs --update, then two rows that carry creature-editor edits (Ghost Chef, Goblin
-- Bandit) taken out of the upsert and given only their new rarity and hearts, so those edits stay.
insert into public.badge_kinds (slug, title, blurb, art, sort, rarity, element, types, rnd, shift, hearts, moves, droppable, active)
select f[1], f[2],
       'A ' || f[3] || ' ' || initcap(f[4]) || case when f[5] <> '' then '/' || initcap(f[5]) else '' end || ' Historikal.',
       'creatures/' || f[1] || '.png', f[7]::int, f[3], case f[4] when 'fire' then 'fire' when 'tide' then 'water' when 'nature' then 'grass' when 'ward' then 'rock' when 'feral' then 'rock' when 'dark' then 'dark' when 'spirit' then 'light' end,
       case when f[5] <> '' then array[f[4], f[5]] else array[f[4]] end, f[8] = '1', f[9] = '1', f[6]::int,
       (select jsonb_agg(jsonb_build_object('name', split_part(m, ':', 1), 'kind', split_part(m, ':', 2)) order by o)
          from unnest(string_to_array(f[10], ';')) with ordinality as x(m, o)),
       true, true
  from (select string_to_array(l, '|') as f from unnest(string_to_array($cat$
